#include "data_safety_model.hpp"
#include "data_safety_store.hpp"
#include "data_safety_page.hpp"
#include <QtWidgets>
#include <QTemporaryDir>
#include <QCryptographicHash>
#include <iostream>
static void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
template<class F>static void refuses(F f){bool failed=false;try{f();}catch(...){failed=true;}check(failed,"expected refusal");}
int main(int argc,char** argv){QApplication app(argc,argv);try{QTemporaryDir dir;auto business=std::make_shared<BusinessStore>(dir.path()+"/business.sqlite");auto before=business->backup();auto beforeHash=dataSafety::baselineHash(before);auto p=dataSafety::defaults();auto bytes=QJsonDocument(before).toJson(QJsonDocument::Compact);auto sha=QString::fromLatin1(QCryptographicHash::hash(bytes,QCryptographicHash::Sha256).toHex());auto plan=dataSafety::inspect(bytes,p,before,sha,"business.json");plan=dataSafety::validateIsolated(plan,before);check(plan["eligible"].toBool()&&plan["checksumState"]=="matched","native isolated verified plan");check(dataSafety::baselineHash(business->backup())==beforeHash,"source business unchanged");refuses([&]{dataSafety::inspect(bytes,p,before,QString(64,'0'));});auto strict=p;strict["requireExternalChecksum"]=true;check(!dataSafety::inspect(bytes,strict,before)["eligible"].toBool(),"checksum setting consumed");auto partial=before;for(auto k:{"topics","relations","collections"})partial.remove(k);auto partialBytes=QJsonDocument(partial).toJson(QJsonDocument::Compact);check(!dataSafety::inspect(partialBytes,p,before)["eligible"].toBool(),"partial blocked default");p["allowPartialBusinessBackup"]=true;check(dataSafety::validateIsolated(dataSafety::inspect(partialBytes,p,before),before)["eligible"].toBool(),"partial allowed only isolated validation");auto secret=before;secret["apiKey"]="never log this";refuses([&]{dataSafety::inspect(QJsonDocument(secret).toJson(),p,before);});
 auto missing=dataSafety::diagnose(QJsonObject{{"id","absent"},{"path",dir.path()+"/missing.sqlite"},{"format","sqlite"}},true);check(!missing["present"].toBool()&&!QFile::exists(dir.path()+"/missing.sqlite"),"diagnostics never create missing database");auto diag=dataSafety::diagnose(QJsonObject{{"id","business"},{"path",business->filePath()},{"format","sqlite"},{"tables",QJsonArray{"records"}}},true);check(diag["integrityState"]=="ok"&&diag["rowCounts"].toObject()["records"].toInt()==2,"read-only real database diagnosis");DataSafetyStore store(dir.path()+"/safety.sqlite");auto stage=store.put("stages",QJsonObject{{"plan",plan}},"");refuses([&]{store.put("stages",QJsonObject{},"stale");});check(store.get("stages")["recordRevision"]==stage["recordRevision"],"CAS protected stage");auto widget=dataSafetyPage(business,nullptr,[=]{return QJsonArray{diag};});check(widget->findChild<QPlainTextEdit*>("dataSafetyInput"),"real independent UI");check(!dataSafetyBack(widget),"main navigation");delete widget;
 auto withPrivate=plan;withPrivate["incoming"]=QJsonObject{{"privateData","PRIVATE-DO-NOT-EXPORT"}};withPrivate["raw"]="PRIVATE-DO-NOT-EXPORT";auto exported=dataSafety::receipt(withPrivate,QJsonObject{{"entries",QJsonArray{QJsonObject{{"id","safe"},{"privateData","PRIVATE-DO-NOT-EXPORT"}}}}});check(!QJsonDocument(exported).toJson().contains("PRIVATE-DO-NOT-EXPORT")&&!exported["plan"].toObject().contains("incoming"),"summary export never includes private body/raw/incoming");
 if(argc>1){QFile file(QString::fromLocal8Bit(argv[1]));check(file.open(QIODevice::ReadOnly),"Java fixture open");auto fixture=QJsonDocument::fromJson(file.readAll()).object();auto normalized=dataSafety::inspect(fixture["source"].toString().toUtf8(),dataSafety::defaults(),fixture["before"].toObject(),fixture["expectedSha"].toString(),"business.json");check(normalized==fixture["plan"].toObject(),"Java Qt normalized entire plan parity");}
 std::cout<<"PASS data safety actual read-only SQLite/missing-file/consumed policies/hash/partial/isolated-native-validation/no-source-write/CAS/private-free-receipt/UI; independent only\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
